import 'package:flutter/material.dart';
import 'package:url_launcher/url_launcher.dart';

import 'api_service.dart';
import 'app_background.dart';

/// Resume-adaptive career roadmap generated by Nexa. Fetched fresh (real-time).
class NexoraRoadmapScreen extends StatefulWidget {
  final String token;
  const NexoraRoadmapScreen({super.key, required this.token});

  @override
  State<NexoraRoadmapScreen> createState() => _NexoraRoadmapScreenState();
}

class _NexoraRoadmapScreenState extends State<NexoraRoadmapScreen> {
  bool isLoading = true;
  String? errorText;
  Map<String, dynamic> data = {};

  @override
  void initState() {
    super.initState();
    _load();
  }

  Future<void> _load() async {
    setState(() {
      isLoading = true;
      errorText = null;
    });
    try {
      final result = await ApiService.getMentorRoadmap(widget.token);
      if (!mounted) return;
      setState(() {
        data = result;
        isLoading = false;
      });
    } catch (e) {
      if (!mounted) return;
      setState(() {
        errorText = e.toString();
        isLoading = false;
      });
    }
  }

  List<String> _asStrings(dynamic v) {
    if (v is List) return v.map((e) => e.toString()).toList();
    return const [];
  }

  Future<void> _openUrl(String url) async {
    final uri = Uri.tryParse(url);
    if (uri == null) return;
    await launchUrl(uri, mode: LaunchMode.externalApplication);
  }

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      backgroundColor: const Color(0xFF0D0D14),
      appBar: AppBar(
        backgroundColor: const Color(0xFF1A1530),
        elevation: 0,
        iconTheme: const IconThemeData(color: Colors.white),
        title: const Text('My Roadmap',
            style: TextStyle(color: Colors.white, fontWeight: FontWeight.w700)),
        actions: [
          IconButton(
            onPressed: isLoading ? null : _load,
            icon: const Icon(Icons.refresh_rounded, color: Colors.white),
          ),
        ],
      ),
      body: AppBackground(
        child: SafeArea(
          child: isLoading
              ? const Center(
                  child: Column(
                    mainAxisSize: MainAxisSize.min,
                    children: [
                      CircularProgressIndicator(color: Color(0xFF7B5CF0)),
                      SizedBox(height: 16),
                      Text('Nexa is reading your resume…',
                          style: TextStyle(color: Colors.white54)),
                    ],
                  ),
                )
              : errorText != null
                  ? Center(
                      child: Padding(
                        padding: const EdgeInsets.all(28),
                        child: Column(
                          mainAxisSize: MainAxisSize.min,
                          children: [
                            Text(errorText!,
                                textAlign: TextAlign.center,
                                style: const TextStyle(color: Colors.white54)),
                            const SizedBox(height: 16),
                            TextButton(
                                onPressed: _load,
                                child: const Text('Try again',
                                    style: TextStyle(color: Color(0xFFB79CFF)))),
                          ],
                        ),
                      ),
                    )
                  : _content(),
        ),
      ),
    );
  }

  Widget _content() {
    final stages = (data['stages'] is List) ? data['stages'] as List : const [];
    final edge = (data['insiderEdge'] is List) ? data['insiderEdge'] as List : const [];
    return SingleChildScrollView(
      padding: const EdgeInsets.all(20),
      child: Column(
        crossAxisAlignment: CrossAxisAlignment.start,
        children: [
          // Detected role + level header
          Container(
            width: double.infinity,
            padding: const EdgeInsets.all(18),
            decoration: BoxDecoration(
              gradient: const LinearGradient(
                  colors: [Color(0xFF7B5CF0), Color(0xFFB06AB3)]),
              borderRadius: BorderRadius.circular(18),
            ),
            child: Column(
              crossAxisAlignment: CrossAxisAlignment.start,
              children: [
                Text('${data['role'] ?? 'Your Path'}',
                    style: const TextStyle(
                        color: Colors.white,
                        fontSize: 20,
                        fontWeight: FontWeight.w800)),
                const SizedBox(height: 2),
                Text('${data['level'] ?? ''}',
                    style: const TextStyle(color: Colors.white, fontSize: 13)),
                if ((data['summary'] ?? '').toString().isNotEmpty) ...[
                  const SizedBox(height: 10),
                  Text('${data['summary']}',
                      style: TextStyle(
                          color: Colors.white.withValues(alpha: 0.92),
                          fontSize: 13,
                          height: 1.4)),
                ],
              ],
            ),
          ),
          const SizedBox(height: 22),
          for (int i = 0; i < stages.length; i++)
            if (stages[i] is Map) _stageCard(i + 1, stages[i] as Map),
          if (edge.isNotEmpty) ...[
            const SizedBox(height: 8),
            const Text('Insider Edge',
                style: TextStyle(
                    color: Colors.white,
                    fontSize: 17,
                    fontWeight: FontWeight.w700)),
            const SizedBox(height: 4),
            const Text('Hand-picked resources for your field',
                style: TextStyle(color: Colors.white54, fontSize: 12.5)),
            const SizedBox(height: 12),
            for (final r in edge)
              if (r is Map) _edgeCard(r),
          ],
          const SizedBox(height: 20),
        ],
      ),
    );
  }

  Widget _stageCard(int index, Map stage) {
    final skills = _asStrings(stage['skills']);
    final steps = _asStrings(stage['steps']);
    return Container(
      margin: const EdgeInsets.only(bottom: 14),
      padding: const EdgeInsets.all(16),
      decoration: BoxDecoration(
        color: Colors.white.withValues(alpha: 0.05),
        borderRadius: BorderRadius.circular(18),
        border: Border.all(color: const Color(0xFF2A2244)),
      ),
      child: Column(
        crossAxisAlignment: CrossAxisAlignment.start,
        children: [
          Row(
            children: [
              CircleAvatar(
                radius: 15,
                backgroundColor: const Color(0xFF7B5CF0),
                child: Text('$index',
                    style: const TextStyle(
                        color: Colors.white,
                        fontWeight: FontWeight.w700,
                        fontSize: 13)),
              ),
              const SizedBox(width: 10),
              Expanded(
                child: Text('${stage['name'] ?? 'Stage'}',
                    style: const TextStyle(
                        color: Colors.white,
                        fontSize: 16,
                        fontWeight: FontWeight.w700)),
              ),
            ],
          ),
          if ((stage['goal'] ?? '').toString().isNotEmpty) ...[
            const SizedBox(height: 8),
            Text('${stage['goal']}',
                style: const TextStyle(
                    color: Colors.white70, fontSize: 13, height: 1.4)),
          ],
          if (skills.isNotEmpty) ...[
            const SizedBox(height: 12),
            Wrap(
              spacing: 8,
              runSpacing: 8,
              children: skills
                  .map((s) => Container(
                        padding: const EdgeInsets.symmetric(
                            horizontal: 12, vertical: 6),
                        decoration: BoxDecoration(
                          color: const Color(0xFF7B5CF0).withValues(alpha: 0.16),
                          borderRadius: BorderRadius.circular(20),
                        ),
                        child: Text(s,
                            style: const TextStyle(
                                color: Color(0xFFB79CFF), fontSize: 12)),
                      ))
                  .toList(),
            ),
          ],
          if (steps.isNotEmpty) ...[
            const SizedBox(height: 12),
            for (final st in steps)
              Padding(
                padding: const EdgeInsets.only(bottom: 6),
                child: Row(
                  crossAxisAlignment: CrossAxisAlignment.start,
                  children: [
                    const Padding(
                      padding: EdgeInsets.only(top: 3),
                      child: Icon(Icons.check_circle_outline_rounded,
                          size: 15, color: Color(0xFF6FDB9A)),
                    ),
                    const SizedBox(width: 8),
                    Expanded(
                      child: Text(st,
                          style: const TextStyle(
                              color: Colors.white70,
                              fontSize: 12.5,
                              height: 1.4)),
                    ),
                  ],
                ),
              ),
          ],
        ],
      ),
    );
  }

  Widget _edgeCard(Map r) {
    final url = (r['url'] ?? '').toString();
    return InkWell(
      onTap: url.isEmpty ? null : () => _openUrl(url),
      borderRadius: BorderRadius.circular(16),
      child: Container(
        margin: const EdgeInsets.only(bottom: 10),
        padding: const EdgeInsets.all(14),
        decoration: BoxDecoration(
          color: Colors.white.withValues(alpha: 0.04),
          borderRadius: BorderRadius.circular(16),
          border: Border.all(color: const Color(0xFF2A2244)),
        ),
        child: Row(
          children: [
            Expanded(
              child: Column(
                crossAxisAlignment: CrossAxisAlignment.start,
                children: [
                  Row(
                    children: [
                      Flexible(
                        child: Text('${r['title'] ?? ''}',
                            style: const TextStyle(
                                color: Colors.white,
                                fontSize: 14.5,
                                fontWeight: FontWeight.w600)),
                      ),
                      if ((r['type'] ?? '').toString().isNotEmpty) ...[
                        const SizedBox(width: 8),
                        Container(
                          padding: const EdgeInsets.symmetric(
                              horizontal: 8, vertical: 2),
                          decoration: BoxDecoration(
                            color: const Color(0xFFB06AB3).withValues(alpha: 0.18),
                            borderRadius: BorderRadius.circular(20),
                          ),
                          child: Text('${r['type']}',
                              style: const TextStyle(
                                  color: Color(0xFFE0A9E0), fontSize: 10)),
                        ),
                      ],
                    ],
                  ),
                  if ((r['why'] ?? '').toString().isNotEmpty) ...[
                    const SizedBox(height: 4),
                    Text('${r['why']}',
                        style: const TextStyle(
                            color: Colors.white54, fontSize: 12, height: 1.35)),
                  ],
                ],
              ),
            ),
            if (url.isNotEmpty)
              const Icon(Icons.open_in_new_rounded,
                  size: 16, color: Colors.white38),
          ],
        ),
      ),
    );
  }
}
